1	package consensus
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"path/filepath"
8		"testing"
9	)
10	
11	// 本文件为“尚未产生本地提议时主动结束轮次”这一现有功能补充回归保障。
12	//
13	// 用户在当前轮次已经提交交易但没有调用 Propose，也可以直接 EndRound：
14	// 这种结束只推进仿真轮次并处理到期交易，不代表确认了一个空块。节点已有
15	// 确认历史、账户已确认序号非零时同样适用（主场景构造在第 1 轮确认、当前
16	// 第 2 轮之上）。
17	//
18	// 成功结束后：
19	//   - 返回轮次与 CurrentRound 都是原轮次 + 1，新轮次仍没有本地提议；
20	//   - 刚结束的轮次可查：Ended=true、UnconfirmedEnd=true、HasRecords=true（有记录
21	//     的无候选轮次不能被当作旧版本未保存详情），候选列表为空（不凭空出现空块
22	//     候选），所有验证者列在未投票名单并按现有公钥次序（十六进制字典序）返回；
23	//   - 确认高度、最新确认块、已有区块的交易顺序及账户已确认序号保持原样；
24	//   - 新轮次在尚未生成提议时，Candidates 按现有约定返回 unknown-round。
25	//
26	// 轮次推进照常处理到期，到期依据是进入后的轮次（而非费用高低）：
27	//   - 同一账户的下一笔待确认交易恰好在新轮次到期、更高序号交易仍有效时，前者
28	//     变为 expired 并保留完整内容供 Tx 查询，不再出现于账户待处理列表；后者继续
29	//     queued 且账户标注 waiting-pack，最早缺口变成刚退出的序号；
30	//   - 另一个账户尚未到期的排队交易继续等待打包，不因主动结束进入等待投票；
31	//   - 完全没有待处理交易时也允许直接结束，轮次记录与确认历史遵守相同规则。
32	//
33	// 保存这次结束结果时发生写入错误：返回错误及轮次 0，当前轮次、候选记录、
34	// 交易状态和账户缺口全部保持操作前结果；不能留下刚结束的轮次记录，也不能
35	// 提前移除那笔将要到期的交易。保存条件恢复正常后再次结束成功。
36	//
37	// 已存在本地提议时的结束、投票确认与各公开调用的兼容性由既有测试覆盖，本文件
38	// 只补足这一现有操作的回归保障，不新增也不改变任何公开行为。
39	
40	// noProposalEndMaxTxs 固定场景的单块上限：取足够大的值，使第 1 轮确认块能
41	// 一次包含两笔交易，后续轮次的池布局只由序号缺口与到期决定。
42	const noProposalEndMaxTxs = 4
43	
44	// noProposalEndTxs 汇总主场景中第 2 轮提交的三笔交易。
45	type noProposalEndTxs struct {
46		// gapExpiring 账户1 seq1 fee 高、expiry=3：恰好在进入第 3 轮时到期，
47		// 是该账户“下一笔待确认交易”，退出后最早缺口变为 1。
48		gapExpiring *Transaction
49		// queuedLater 账户1 seq2 expiry=100：序号更高且仍有效，到期后继续
50		// queued/waiting-pack；费用低于 gapExpiring，钉住“费用不能改变失效结果”。
51		queuedLater *Transaction
52		// otherWaiting 账户2 seq1 expiry=100：尚未到期，继续 waiting-pack，
53		// 不因主动结束进入 waiting-vote。
54		otherWaiting *Transaction
55	}
56	
57	// noProposalEndScene 是无候选结束主场景的全部句柄。
58	type noProposalEndScene struct {
59		keys []testKey
60		// valCount 为验证者人数（keys 的前 valCount 把）；主场景为 4，
61		// 零历史空场景可使用更少验证者。
62		valCount      int
63		dir           string
64		n             *Node
65		round1Block   Block // 第 1 轮确认的高度 1 区块（含两笔交易，顺序固定）
66		round1TxAlice *Transaction
67		round1TxBob   *Transaction
68		round2        noProposalEndTxs
69	}
70	
71	// buildNoProposalEndScene 在一块确认历史之上构造第 2 轮“已提交但未提议”场景。
72	//
73	// 第 1 轮：账户0 seq1（费用 5）与账户3 seq1（费用 8）被本地提议一起确认
74	// （单块上限 4），账户0、账户3 的已确认序号推进为 1，节点进入第 2 轮、高度 1。
75	//
76	// 第 2 轮不调用 Propose，直接提交：
77	//
78	//	gapExpiring  账户1 seq1 fee=9 expiry=3    恰好进入轮次 3 时失效
79	//	queuedLater  账户1 seq2 fee=2 expiry=100  更高序号仍有效（低费用）
80	//	otherWaiting 账户2 seq1 fee=1 expiry=100  未到期，另一账户
81	//
82	// 四把密钥全部为验证者，发送者复用同一名单。
83	func buildNoProposalEndScene(t *testing.T) *noProposalEndScene {
84		t.Helper()
85		keys := genKeys(t, 4)
86		dir := t.TempDir()
87		vals := make([][]byte, 4)
88		for i := range vals {
89			vals[i] = keys[i].pub
90		}
91		n, err := New(dir, Config{
92			Seed:           []byte("end-round-no-proposal-seed"),
93			Validators:     vals,
94			MaxTxsPerBlock: noProposalEndMaxTxs,
95		})
96		if err != nil {
97			t.Fatal(err)
98		}
99	
100		// 第 1 轮确认历史：两笔不同账户的交易进入同一确认块，费用 8 的账户3
101		// 交易按打包规则排在费用 5 的账户0 交易之前。
102		alice := NewTransaction(keys[0].priv, 1, []byte("round1-alice"), 5, 100)
103		bob := NewTransaction(keys[3].priv, 1, []byte("round1-bob"), 8, 100)
104		for _, tx := range []*Transaction{alice, bob} {
105			if _, err := n.Submit(tx); err != nil {
106				t.Fatalf("submit %q: %v", tx.Content, err)
107			}
108		}
109		p1, err := n.Propose()
110		if err != nil {
111			t.Fatal(err)
112		}
113		wantOrder := []string{bob.ID(), alice.ID()}
114		if fmt.Sprint(p1.TxIDs) != fmt.Sprint(wantOrder) {
115			t.Fatalf("setup: round 1 proposal order = %v, want %v", p1.TxIDs, wantOrder)
116		}
117		// 四验证者门槛为 3 票（严格超过 2/3）；keys[4] 不是验证者，手动投三票。
118		for i := 0; i < 3; i++ {
119			res, err := n.Vote(keys[i].pub, 1, p1.BlockID)
120			if err != nil || !res.Counted {
121				t.Fatalf("round 1 confirming vote %d: %+v %v", i+1, res, err)
122			}
123			if (i == 2) != res.Confirmed {
124				t.Fatalf("round 1 vote %d confirmed=%v, want %v", i+1, res.Confirmed, i == 2)
125			}
126		}
127		if n.CurrentRound() != 2 || n.Height() != 1 {
128			t.Fatalf("setup: round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
129		}
130		blk, err := n.BlockAt(1)
131		if err != nil {
132			t.Fatal(err)
133		}
134	
135		// 第 2 轮：只提交，不提议。
136		scene := &noProposalEndScene{
137			keys:          keys,
138			valCount:      4,
139			dir:           dir,
140			n:             n,
141			round1Block:   blk,
142			round1TxAlice: alice,
143			round1TxBob:   bob,
144			round2: noProposalEndTxs{
145				gapExpiring:  NewTransaction(keys[1].priv, 1, []byte("gap-expiring"), 9, 3),
146				queuedLater:  NewTransaction(keys[1].priv, 2, []byte("queued-later"), 2, 100),
147				otherWaiting: NewTransaction(keys[2].priv, 1, []byte("other-waiting"), 1, 100),
148			},
149		}
150		for _, tx := range []*Transaction{scene.round2.gapExpiring, scene.round2.queuedLater, scene.round2.otherWaiting} {
151			if _, err := n.Submit(tx); err != nil {
152				t.Fatalf("submit %q: %v", tx.Content, err)
153			}
154		}
155		return scene
156	}
157	
158	// assertConfirmedBlockPreserved 断言确认高度、最新确认块与高度 1 区块的
159	// 交易顺序完全保持第 1 轮确认时的原样。
160	func (s *noProposalEndScene) assertConfirmedBlockPreserved(t *testing.T, n *Node) {
161		t.Helper()
162		if n.Height() != 1 {
163			t.Fatalf("confirmed height = %d, want 1 (ending a proposal-less round confirms nothing)", n.Height())
164		}
165		blk, err := n.BlockAt(1)
166		if err != nil {
167			t.Fatal(err)
168		}
169		assertSameBlock(t, "block at height 1", blk, s.round1Block)
170		if latest, ok := n.LatestBlock(); !ok {
171			t.Fatal("latest confirmed block disappeared")
172		} else {
173			assertSameBlock(t, "latest block", latest, s.round1Block)
174		}
175		if _, err := n.BlockAt(2); reason(err) != ReasonUnknownBlock {
176			t.Fatalf("block at height 2: %v, want %s", err, ReasonUnknownBlock)
177		}
178	}
179	
180	// assertConfirmedAccountsPreserved 断言已确认的两笔交易与其账户序号不变。
181	func (s *noProposalEndScene) assertConfirmedAccountsPreserved(t *testing.T, n *Node) {
182		t.Helper()
183		for _, x := range []struct {
184			tx        *Transaction
185			account   []byte
186			confirmed uint64
187		}{
188			{s.round1TxAlice, s.keys[0].pub, 1},
189			{s.round1TxBob, s.keys[3].pub, 1},
190		} {
191			info := n.mustTx(t, x.tx.ID())
192			if info.Status != StatusConfirmed || info.BlockHeight != 1 || info.BlockID != s.round1Block.ID {
193				t.Fatalf("confirmed tx %q changed: %+v", x.tx.Content, info)
194			}
195			if a := n.Account(x.account); a.ConfirmedSequence != x.confirmed {
196				t.Fatalf("account %x confirmed seq = %d, want %d", x.account, a.ConfirmedSequence, x.confirmed)
197			}
198		}
199	}
200	
201	// assertAllValidatorsUnvoted 断言未投票名单恰为全部验证者并按现有公钥次序
202	// （公钥十六进制字典序）返回，钉住排序约定。
203	func (s *noProposalEndScene) assertAllValidatorsUnvoted(t *testing.T, rc *RoundCandidates) {
204		t.Helper()
205		want := make([][]byte, s.valCount)
206		for i := range want {
207			want[i] = s.keys[i].pub
208		}
209		// 期望次序即现有公钥次序（十六进制字典序）；got 保持返回时的原始次序，
210		// 不再排序，以便真正钉住“按公钥次序返回”而不只是集合相等。
211		gotOrder := make([]string, len(rc.Unvoted))
212		for i, pub := range rc.Unvoted {
213			gotOrder[i] = fmt.Sprintf("%x", pub)
214		}
215		if fmt.Sprint(gotOrder) != fmt.Sprint(hexKeys(want)) {
216			t.Fatalf("unvoted validators = %x\nwant %x (all validators in public-key order)", rc.Unvoted, want)
217		}
218		if len(rc.Unvoted) != s.valCount {
219			t.Fatalf("unvoted count = %d, want %d", len(rc.Unvoted), s.valCount)
220		}
221	}
222	
223	// assertEndedRecordIsNotEmptyBlock 断言刚结束的无候选轮次：
224	//   - 已结束、未确认、有详情记录（不是旧版本 DetailMissing 轮）；
225	//   - 候选列表为空且不凭空出现空块候选；
226	//   - 全部验证者按公钥次序列为未投票。
227	func (s *noProposalEndScene) assertEndedRecordIsNotEmptyBlock(t *testing.T, n *Node, endedRound uint64) {
228		t.Helper()
229		rc, err := n.Candidates(endedRound)
230		if err != nil {
231			t.Fatalf("Candidates(%d) on just-ended round: %v", endedRound, err)
232		}
233		if rc.Round != endedRound || !rc.Ended || !rc.UnconfirmedEnd || !rc.HasRecords {
234			t.Fatalf("ended proposal-less round %d view = %+v, want ended/unconfirmed/with-records", endedRound, rc)
235		}
236		if len(rc.Candidates) != 0 {
237			t.Fatalf("proposal-less end must not fabricate an empty-block candidate: %+v", rc.Candidates)
238		}
239		s.assertAllValidatorsUnvoted(t, rc)
240	}
241	
242	// assertNewRoundHasNoProposal 断言当前轮次为 wantRound、仍无本地提议，
243	// 且此时 Candidates 按现有约定返回 unknown-round（而不是返回空记录）。
244	func (s *noProposalEndScene) assertNewRoundHasNoProposal(t *testing.T, n *Node, wantRound uint64) {
245		t.Helper()
246		if n.CurrentRound() != wantRound {
247			t.Fatalf("current round = %d, want %d", n.CurrentRound(), wantRound)
248		}
249		if p, ok := n.Proposal(); ok {
250			t.Fatalf("new round %d must not inherit a local proposal: %+v", wantRound, p)
251		}
252		if _, err := n.Candidates(wantRound); reason(err) != ReasonUnknownRound {
253			t.Fatalf("Candidates(%d) before any proposal = %v, want %s", wantRound, err, ReasonUnknownRound)
254		}
255	}
256	
257	// assertExpiryOutcome 钉住进入 newRound 后的到期结果：
258	//   - gapExpiring 查为 expired、完整内容与费用/到期轮次保留、不带确认块或替代关联；
259	//   - queuedLater 仍 queued/waiting-pack，账户1 只剩它一笔、确认序号仍为 0、
260	//     最早缺口变成刚退出的序号 1；
261	//   - otherWaiting 在另一账户继续 queued/waiting-pack，序号 0、无缺口；
262	//   - 确认历史与账户确认序号不变。
263	func (s *noProposalEndScene) assertExpiryOutcome(t *testing.T, n *Node, newRound uint64) {
264		t.Helper()
265		x := s.round2
266	
267		// 到期交易变成 expired，完整字段仍可通过 Tx 查询。
268		exp := n.mustTx(t, x.gapExpiring.ID())
269		if exp.Status != StatusExpired {
270			t.Fatalf("gap-expiring status = %s, want expired on entering round %d", exp.Status, newRound)
271		}
272		if exp.BlockHeight != 0 || exp.BlockID != "" || exp.ReplacedBy != "" ||
273			exp.DropReason != "" || exp.DropRound != 0 {
274			t.Fatalf("expired tx must carry no block/replace/drop associations: %+v", exp)
275		}
276		if exp.Tx == nil || string(exp.Tx.Content) != "gap-expiring" ||
277			exp.Tx.Sequence != 1 || exp.Tx.Fee != 9 || exp.Tx.Expiry != 3 ||
278			fmt.Sprintf("%x", exp.Tx.Sender) != fmt.Sprintf("%x", x.gapExpiring.Sender) ||
279			fmt.Sprintf("%x", exp.Tx.Signature) != fmt.Sprintf("%x", x.gapExpiring.Signature) {
280			t.Fatalf("expired tx content not preserved in full: %+v", exp.Tx)
281		}
282	
283		// 更高序号交易仍 queued；账户1 待处理只剩 seq2 一笔且为 waiting-pack；
284		// 已确认序号仍为 0，最早缺口变成刚退出的序号 1。
285		assertAccountQueue(t, n, s.keys[1].pub, 0, map[string]string{
286			x.queuedLater.ID(): "waiting-pack",
287		})
288		if a := n.Account(s.keys[1].pub); a.Gap != 1 {
289			t.Fatalf("account 1 gap = %d, want 1 after seq1 expired away", a.Gap)
290		}
291		ql := n.mustTx(t, x.queuedLater.ID())
292		if ql.Status != StatusQueued {
293			t.Fatalf("higher-sequence tx status = %s, want queued", ql.Status)
294		}
295	
296		// 另一账户未到期交易继续等待打包，绝不因主动结束进入等待投票。
297		assertAccountQueue(t, n, s.keys[2].pub, 0, map[string]string{
298			x.otherWaiting.ID(): "waiting-pack",
299		})
300		if a := n.Account(s.keys[2].pub); a.Gap != 0 {
301			t.Fatalf("account 2 gap = %d, want 0", a.Gap)
302		}
303	
304		s.assertConfirmedAccountsPreserved(t, n)
305	}
306	
307	// assertRoundTwoBeforeEnd 断言结束前（或失败结束后）节点仍处于第 2 轮
308	// 无本地提议状态：三笔交易全部 queued/waiting-pack；账户1 有 seq1、seq2
309	// 无缺口，账户2 有 seq1；确认历史原样；对第 2 轮的候选查询按 unknown-round
310	// 处理（没有留下任何轮次记录）。
311	func (s *noProposalEndScene) assertRoundTwoBeforeEnd(t *testing.T, n *Node) {
312		t.Helper()
313		if n.CurrentRound() != 2 {
314			t.Fatalf("current round = %d, want 2", n.CurrentRound())
315		}
316		if p, ok := n.Proposal(); ok {
317			t.Fatalf("no local proposal should exist before EndRound: %+v", p)
318		}
319		s.assertConfirmedBlockPreserved(t, n)
320		s.assertConfirmedAccountsPreserved(t, n)
321	
322		x := s.round2
323		assertAccountQueue(t, n, s.keys[1].pub, 0, map[string]string{
324			x.gapExpiring.ID(): "waiting-pack",
325			x.queuedLater.ID(): "waiting-pack",
326		})
327		if a := n.Account(s.keys[1].pub); a.Gap != 0 {
328			t.Fatalf("account 1 gap = %d, want 0 before the end", a.Gap)
329		}
330		assertAccountQueue(t, n, s.keys[2].pub, 0, map[string]string{
331			x.otherWaiting.ID(): "waiting-pack",
332		})
333		for _, tx := range []*Transaction{x.gapExpiring, x.queuedLater, x.otherWaiting} {
334			info := n.mustTx(t, tx.ID())
335			if info.Status != StatusQueued {
336				t.Fatalf("tx %q status = %s, want queued before end", tx.Content, info.Status)
337			}
338		}
339	
340		// 尚未产生提议的当前轮次没有轮次记录，候选查询按未知轮次处理；
341		// 失败的结束不能在这里留下“已结束”的轮次记录。
342		if _, err := n.Candidates(2); reason(err) != ReasonUnknownRound {
343			t.Fatalf("Candidates(2) without proposal = %v, want %s", err, ReasonUnknownRound)
344		}
345	}
346	
347	// TestEndRoundWithoutProposalAdvancesAndExpires 覆盖无本地提议结束的主回归序列：
348	// 第 1 轮有确认历史与非零账户序号，第 2 轮只提交不提议，直接 EndRound 成功
349	// 推进到第 3 轮并处理到期；空候选结束记录、全部验证者未投票排序、无空块、
350	// 确认历史与区块顺序不变、新轮 unknown-round、到期/排队/缺口/内容保留全部钉住；
351	// 成功结果重开后一致。
352	func TestEndRoundWithoutProposalAdvancesAndExpires(t *testing.T) {
353		s := buildNoProposalEndScene(t)
354		s.assertRoundTwoBeforeEnd(t, s.n)
355	
356		nextRound, err := s.n.EndRound()
357		if err != nil {
358			t.Fatalf("EndRound without proposal: %v", err)
359		}
360		if nextRound != 3 {
361			t.Fatalf("EndRound return = %d, want 3", nextRound)
362		}
363		s.assertNewRoundHasNoProposal(t, s.n, 3)
364		s.assertEndedRecordIsNotEmptyBlock(t, s.n, 2)
365		s.assertConfirmedBlockPreserved(t, s.n)
366		s.assertExpiryOutcome(t, s.n, 3)
367	
368		// 在第 3 轮仍不提议、直接再结束一次：池内剩余两笔交易到期轮次为 100，
369		// 既不会被打包也不会到期，同样允许无候选结束并进入第 4 轮；轮次记录与
370		// 确认历史遵守相同规则。（完全空池的结束由 FreshNodeEmptyPool 用例覆盖。）
371		nextRound, err = s.n.EndRound()
372		if err != nil {
373			t.Fatalf("second EndRound with empty pool: %v", err)
374		}
375		if nextRound != 4 {
376			t.Fatalf("second EndRound return = %d, want 4", nextRound)
377		}
378		s.assertNewRoundHasNoProposal(t, s.n, 4)
379		s.assertEndedRecordIsNotEmptyBlock(t, s.n, 3)
380		s.assertConfirmedBlockPreserved(t, s.n)
381		s.assertExpiryOutcome(t, s.n, 3)
382	
383		// 成功结果持久化：重开节点看到完全一致的第 4 轮状态与两条结束记录。
384		reopened, err := Open(s.dir)
385		if err != nil {
386			t.Fatal(err)
387		}
388		s.assertNewRoundHasNoProposal(t, reopened, 4)
389		s.assertEndedRecordIsNotEmptyBlock(t, reopened, 2)
390		s.assertEndedRecordIsNotEmptyBlock(t, reopened, 3)
391		s.assertConfirmedBlockPreserved(t, reopened)
392		s.assertExpiryOutcome(t, reopened, 3)
393	}
394	
395	// TestEndRoundWithoutProposalFreshNodeEmptyPool 钉住零历史节点也允许在
396	// 没有任何待处理交易、没有本地提议时直接结束：返回原轮次 + 1，结束记录为空、
397	// 未确认且有详情，全部验证者未投票；高度仍为 0，新轮无提议时候选查询为
398	// unknown-round；连续两次结束行为一致。
399	func TestEndRoundWithoutProposalFreshNodeEmptyPool(t *testing.T) {
400		keys := genKeys(t, 3)
401		n, _ := newTestNode(t, keys, 2)
402		scene := &noProposalEndScene{keys: keys, valCount: 3}
403	
404		if n.Height() != 0 {
405			t.Fatalf("fresh height = %d, want 0", n.Height())
406		}
407		r, err := n.EndRound()
408		if err != nil {
409			t.Fatalf("EndRound on fresh empty node: %v", err)
410		}
411		if r != 2 || n.CurrentRound() != 2 {
412			t.Fatalf("round after end = %d (current %d), want 2", r, n.CurrentRound())
413		}
414		if n.Height() != 0 {
415			t.Fatalf("height after empty end = %d, want 0", n.Height())
416		}
417		if _, ok := n.LatestBlock(); ok {
418			t.Fatal("empty proposal-less end must not produce a latest block")
419		}
420		scene.assertEndedRecordIsNotEmptyBlock(t, n, 1)
421		scene.assertNewRoundHasNoProposal(t, n, 2)
422	
423		r, err = n.EndRound()
424		if err != nil {
425			t.Fatalf("second EndRound on fresh node: %v", err)
426		}
427		if r != 3 || n.CurrentRound() != 3 {
428			t.Fatalf("round after second end = %d (current %d), want 3", r, n.CurrentRound())
429		}
430		scene.assertEndedRecordIsNotEmptyBlock(t, n, 2)
431		scene.assertNewRoundHasNoProposal(t, n, 3)
432		if n.Height() != 0 {
433			t.Fatalf("height = %d, want 0 after two empty ends", n.Height())
434		}
435	}
436	
437	// TestEndRoundWithoutProposalFeeDoesNotChangeEviction 钉住到期只取决于
438	// “进入后的轮次”：下一笔待确认交易即使费用很高，也必须在新轮次恰为其
439	// 到期轮次时失效；更高序号的零费用交易（不能被前者“带过去”）继续排队。
440	func TestEndRoundWithoutProposalFeeDoesNotChangeEviction(t *testing.T) {
441		keys := genKeys(t, 4)
442		n, _ := newTestNode(t, keys, 4)
443		// 当前第 2 轮：账户0 已确认 seq1（第 1 轮空历史不构造，直接利用初始状态
444		// 在第 1 轮提交并确认一笔），使 seq2 成为“账户已确认序号非零”的下一笔。
445		first := NewTransaction(keys[0].priv, 1, []byte("first"), 1, 100)
446		if _, err := n.Submit(first); err != nil {
447			t.Fatal(err)
448		}
449		p1, err := n.Propose()
450		if err != nil {
451			t.Fatal(err)
452		}
453		for i := 0; i < 3; i++ {
454			if res, err := n.Vote(keys[i].pub, 1, p1.BlockID); err != nil || !res.Counted {
455				t.Fatalf("confirm vote %d: %+v %v", i+1, res, err)
456			}
457		}
458		if n.CurrentRound() != 2 {
459			t.Fatalf("setup: current round = %d, want 2", n.CurrentRound())
460		}
461	
462		// seq2 费用极高但恰好进入第 3 轮到期；seq3 费用为 0 但到期更远，必须留下。
463		head := NewTransaction(keys[0].priv, 2, []byte("high-fee-expiring"), 1_000_000, 3)
464		tail := NewTransaction(keys[0].priv, 3, []byte("zero-fee-valid"), 0, 100)
465		if _, err := n.Submit(head); err != nil {
466			t.Fatal(err)
467		}
468		if _, err := n.Submit(tail); err != nil {
469			t.Fatal(err)
470		}
471	
472		if r, err := n.EndRound(); err != nil || r != 3 {
473			t.Fatalf("EndRound = %d, %v, want 3", r, err)
474		}
475		hinfo := n.mustTx(t, head.ID())
476		if hinfo.Status != StatusExpired {
477			t.Fatalf("high-fee head tx status = %s, want expired (fee must not override expiry)", hinfo.Status)
478		}
479		assertAccountQueue(t, n, keys[0].pub, 1, map[string]string{tail.ID(): "waiting-pack"})
480		if a := n.Account(keys[0].pub); a.Gap != 2 {
481			t.Fatalf("account gap = %d, want 2 (the just-expired sequence)", a.Gap)
482		}
483		tinfo := n.mustTx(t, tail.ID())
484		if tinfo.Status != StatusQueued {
485			t.Fatalf("zero-fee tail tx status = %s, want queued", tinfo.Status)
486		}
487	}
488	
489	// TestEndRoundWithoutProposalEmptyPoolAfterHistory 钉住“完全没有待处理交易”
490	// 与“已有确认历史、账户已确认序号非零”两个条件同时成立时也允许直接结束：
491	// 第 1 轮确认一笔后进入第 2 轮，第 2 轮不提交任何交易、不提议，直接 EndRound。
492	// 结束记录为空、未确认且有详情，全部验证者未投票；确认高度、最新确认块与区块
493	// 交易顺序保持原样，已确认账户序号不回退；新轮次仍无提议、候选查询 unknown-round。
494	func TestEndRoundWithoutProposalEmptyPoolAfterHistory(t *testing.T) {
495		keys := genKeys(t, 4)
496		n, dir := newTestNode(t, keys, 4)
497		scene := &noProposalEndScene{keys: keys, valCount: 4, dir: dir, n: n}
498	
499		confirmed := NewTransaction(keys[0].priv, 1, []byte("only-confirmed"), 7, 100)
500		if _, err := n.Submit(confirmed); err != nil {
501			t.Fatal(err)
502		}
503		p1, err := n.Propose()
504		if err != nil {
505			t.Fatal(err)
506		}
507		if fmt.Sprint(p1.TxIDs) != fmt.Sprint([]string{confirmed.ID()}) {
508			t.Fatalf("setup: round 1 proposal = %v, want [%s]", p1.TxIDs, confirmed.ID())
509		}
510		for i := 0; i < 3; i++ {
511			if res, err := n.Vote(keys[i].pub, 1, p1.BlockID); err != nil || !res.Counted {
512				t.Fatalf("confirm vote %d: %+v %v", i+1, res, err)
513			}
514		}
515		blk, err := n.BlockAt(1)
516		if err != nil {
517			t.Fatal(err)
518		}
519		scene.round1Block = blk
520	
521		// 第 2 轮：池内完全没有待处理交易，也没有本地提议——直接结束。
522		if a := n.Account(keys[0].pub); a.ConfirmedSequence != 1 || len(a.Pending) != 0 {
523			t.Fatalf("setup: account 0 = %+v, want confirmed seq 1 with empty pending", a)
524		}
525		r, err := n.EndRound()
526		if err != nil {
527			t.Fatalf("EndRound with empty pool after history: %v", err)
528		}
529		if r != 3 || n.CurrentRound() != 3 {
530			t.Fatalf("round after end = %d (current %d), want 3", r, n.CurrentRound())
531		}
532		scene.assertEndedRecordIsNotEmptyBlock(t, n, 2)
533		scene.assertNewRoundHasNoProposal(t, n, 3)
534		scene.assertConfirmedBlockPreserved(t, n)
535		if a := n.Account(keys[0].pub); a.ConfirmedSequence != 1 || len(a.Pending) != 0 || a.Gap != 0 {
536			t.Fatalf("confirmed account changed after empty end: %+v", a)
537		}
538		info := n.mustTx(t, confirmed.ID())
539		if info.Status != StatusConfirmed || info.BlockHeight != 1 || info.BlockID != blk.ID {
540			t.Fatalf("confirmed tx changed: %+v", info)
541		}
542	
543		// 持久化：重开后空结束记录与确认历史一致。
544		reopened, err := Open(dir)
545		if err != nil {
546			t.Fatal(err)
547		}
548		scene.assertEndedRecordIsNotEmptyBlock(t, reopened, 2)
549		scene.assertNewRoundHasNoProposal(t, reopened, 3)
550		scene.assertConfirmedBlockPreserved(t, reopened)
551	}
552	
553	// TestEndRoundWithoutProposalSaveFailureAtomic 钉住无候选结束保存失败时的
554	// 原子性：返回错误与轮次 0，当前轮次、候选记录（第 2 轮仍 unknown-round、
555	// 不留结束记录）、交易状态与账户缺口全部保持操作前；磁盘文件逐字节不变、
556	// 无临时文件，重开一致；恢复后再次 EndRound 按规则成功并持久化。
557	func TestEndRoundWithoutProposalSaveFailureAtomic(t *testing.T) {
558		s := buildNoProposalEndScene(t)
559		s.assertRoundTwoBeforeEnd(t, s.n)
560	
561		statePath := filepath.Join(s.dir, stateFileName)
562		before, err := os.ReadFile(statePath)
563		if err != nil {
564			t.Fatal(err)
565		}
566	
567		// 无候选结束因写入错误失败：必须返回错误与轮次 0，且是基础设施错误而非拒绝。
568		s.n.injectSaveErr = errors.New("disk full (simulated)")
569		nextRound, err := s.n.EndRound()
570		s.n.injectSaveErr = nil
571		if err == nil {
572			t.Fatal("EndRound must return an error when saving fails")
573		}
574		if reason(err) != "" {
575			t.Fatalf("save failure must surface as infrastructure error, not rejection %q: %v", reason(err), err)
576		}
577		if nextRound != 0 {
578			t.Fatalf("returned round = %d, want 0 on save failure", nextRound)
579		}
580	
581		// 内存：轮次、候选记录、交易状态与账户缺口全部保持操作前。
582		s.assertRoundTwoBeforeEnd(t, s.n)
583	
584		// 磁盘：文件逐字节不变，目录中只有 state.json，不残留临时文件，
585		// 也没有提前移除那笔将要到期的交易。
586		after, err := os.ReadFile(statePath)
587		if err != nil {
588			t.Fatal(err)
589		}
590		if string(after) != string(before) {
591			t.Fatal("state file changed despite the failed save")
592		}
593		entries, err := os.ReadDir(s.dir)
594		if err != nil {
595			t.Fatal(err)
596		}
597		var names []string
598		for _, e := range entries {
599			names = append(names, e.Name())
600		}
601		if fmt.Sprint(names) != "[state.json]" {
602			t.Fatalf("failed save must not leave temp files, dir contains %v", names)
603		}
604	
605		// 重开：同样停在第 2 轮无提议状态，那笔将到期交易仍在池中。
606		reopened, err := Open(s.dir)
607		if err != nil {
608			t.Fatal(err)
609		}
610		s.assertRoundTwoBeforeEnd(t, reopened)
611	
612		// 保存恢复正常后再次结束：按规则成功进入第 3 轮并持久化。
613		nextRound, err = reopened.EndRound()
614		if err != nil {
615			t.Fatalf("EndRound after recovery: %v", err)
616		}
617		if nextRound != 3 {
618			t.Fatalf("EndRound after recovery = %d, want 3", nextRound)
619		}
620		s.assertNewRoundHasNoProposal(t, reopened, 3)
621		s.assertEndedRecordIsNotEmptyBlock(t, reopened, 2)
622		s.assertConfirmedBlockPreserved(t, reopened)
623		s.assertExpiryOutcome(t, reopened, 3)
624	
625		durable, err := Open(s.dir)
626		if err != nil {
627			t.Fatal(err)
628		}
629		s.assertNewRoundHasNoProposal(t, durable, 3)
630		s.assertEndedRecordIsNotEmptyBlock(t, durable, 2)
631		s.assertExpiryOutcome(t, durable, 3)
632	}
