226		// 建立 orig -> mid -> last 的替换链（费用 1 -> 5 -> 9）。
227		orig := NewTransaction(keys[0].priv, 1, []byte("rej-orig"), 1, 100)
228		mid := NewTransaction(keys[0].priv, 1, []byte("rej-mid"), 5, 100)
229		last := NewTransaction(keys[0].priv, 1, []byte("rej-last"), 9, 100)
230		for _, tx := range []*Transaction{orig, mid, last} {
231			if _, err := n.Submit(tx); err != nil {
232				t.Fatal(err)
233			}
234		}
235		origID, midID, lastID := orig.ID(), mid.ID(), last.ID()
236	
237		// 场景前提：尚未产生提议，最新交易仍在排队。
238		if _, ok := n.Proposal(); ok {
239			t.Fatal("test setup: no proposal must exist yet")
240		}
241		if info, _ := n.Tx(lastID); info.Status != StatusQueued {
242			t.Fatalf("test setup: latest status = %s, want queued", info.Status)
243		}
244		entriesBefore := len(n.st.Entries)
245	
246		// 拒绝一：标识不同、费用与当前交易相等（9）的替换尝试。
247		equalFee := NewTransaction(keys[0].priv, 1, []byte("rej-equal"), 9, 100)
248		if equalFee.ID() == lastID {
249			t.Fatal("test setup: equal-fee tx must have a distinct id")
250		}
251		res, err := n.Submit(equalFee)
252		if reason(err) != ReasonLowFee {
253			t.Fatalf("equal-fee replacement reason = %v, want %s", err, ReasonLowFee)
254		}
255		if res != nil {
256			t.Fatalf("rejected submit must return nil result, got %+v", res)
257		}
258		if _, err := n.Tx(equalFee.ID()); reason(err) != ReasonUnknownTx {
259			t.Fatalf("equal-fee tx lookup = %v, want %s (no history kept)", err, ReasonUnknownTx)
260		}
261	
262		// 拒绝二：标识不同、费用低于当前交易（6 < 9，虽高于中间那笔的 5）的替换尝试。
263		// 费用比较只针对当前排队交易，与任何历史交易无关。
264		lowerFee := NewTransaction(keys[0].priv, 1, []byte("rej-lower"), 6, 100)
265		res, err = n.Submit(lowerFee)
266		if reason(err) != ReasonLowFee {
267			t.Fatalf("lower-fee replacement reason = %v, want %s", err, ReasonLowFee)
268		}
269		if res != nil {
270			t.Fatalf("rejected submit must return nil result, got %+v", res)
271		}
272		if _, err := n.Tx(lowerFee.ID()); reason(err) != ReasonUnknownTx {
273			t.Fatalf("lower-fee tx lookup = %v, want %s (no history kept)", err, ReasonUnknownTx)
274		}
275	
276		// 拒绝三：按原始内容与签名重投已被替换的原交易。
277		replayOrig := NewTransaction(keys[0].priv, 1, []byte("rej-orig"), 1, 100)
278		if replayOrig.ID() != origID {
279			t.Fatalf("test setup: byte-identical replay id %s != original %s", replayOrig.ID(), origID)
280		}
281		res, err = n.Submit(replayOrig)
282		if reason(err) != ReasonDuplicate {
283			t.Fatalf("replay of replaced orig reason = %v, want %s", err, ReasonDuplicate)
284		}
285		if res != nil {
286			t.Fatalf("rejected submit must return nil result, got %+v", res)
287		}
288	
289		// 拒绝四：按原始内容与签名重投已被替换的中间交易。
290		replayMid := NewTransaction(keys[0].priv, 1, []byte("rej-mid"), 5, 100)
291		if replayMid.ID() != midID {
292			t.Fatalf("test setup: byte-identical replay id %s != mid %s", replayMid.ID(), midID)
293		}
294		res, err = n.Submit(replayMid)
295		if reason(err) != ReasonDuplicate {
296			t.Fatalf("replay of replaced mid reason = %v, want %s", err, ReasonDuplicate)
297		}
298		if res != nil {
299			t.Fatalf("rejected submit must return nil result, got %+v", res)
300		}
301	
302		// 拒绝不留副作用：不新增记录、不推进轮次、不增加确认高度。
303		if got := len(n.st.Entries); got != entriesBefore {
304			t.Fatalf("entries changed %d -> %d after rejections", entriesBefore, got)
305		}
306		if n.CurrentRound() != 1 || n.Height() != 0 {
307			t.Fatalf("round/height = %d/%d, want 1/0 after rejections", n.CurrentRound(), n.Height())
308		}
309	
310		// 已有替换关联保持原样：orig -> mid -> last，不跨步改指。
311		origInfo, err := n.Tx(origID)
312		if err != nil {
313			t.Fatal(err)
314		}
315		if origInfo.Status != StatusReplaced || origInfo.ReplacedBy != midID {
316			t.Fatalf("orig record after rejections = %+v, want replaced/%s", origInfo, midID)
317		}
318		assertTxMatches(t, origInfo.Tx, orig)
319		midInfo, err := n.Tx(midID)
320		if err != nil {
321			t.Fatal(err)
322		}
323		if midInfo.Status != StatusReplaced || midInfo.ReplacedBy != lastID {
324			t.Fatalf("mid record after rejections = %+v, want replaced/%s", midInfo, lastID)
325		}
326		assertTxMatches(t, midInfo.Tx, mid)
327	
328		// 最新排队交易与其他账户交易均保持原样。
329		lastInfo, err := n.Tx(lastID)
330		if err != nil {
331			t.Fatal(err)
332		}
333		if lastInfo.Status != StatusQueued || lastInfo.ReplacedBy != "" {
334			t.Fatalf("latest record after rejections = %+v, want queued with no link", lastInfo)
335		}
336		assertTxMatches(t, lastInfo.Tx, last)
337		otherInfo, err := n.Tx(other.ID())
338		if err != nil {
339			t.Fatal(err)
340		}
341		if otherInfo.Status != StatusQueued {
342			t.Fatalf("bystander tx changed: %+v", otherInfo)
343		}
344		assertTxMatches(t, otherInfo.Tx, other)
345		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{lastID: "waiting-pack"})
346		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{other.ID(): "waiting-pack"})
347	
348		// 随后提交合法的更高费用交易：仍按既有规则正常替换最新交易。
349		final := NewTransaction(keys[0].priv, 1, []byte("rej-final"), 10, 100)
350		res, err = n.Submit(final)
351		if err != nil {
352			t.Fatalf("valid higher-fee tx must still replace after rejections: %v", err)
353		}
354		if res.TxID != final.ID() || res.ReplacedID != lastID || res.EvictedID != "" {
355			t.Fatalf("final replacement result = %+v, want accept %s replacing %s", res, final.ID(), lastID)
356		}
357		// 链条延长一步：last -> final；更早的关联仍不跨步改指。
358		if info, _ := n.Tx(lastID); info.Status != StatusReplaced || info.ReplacedBy != final.ID() {
359			t.Fatalf("last record = %+v, want replaced/%s", info, final.ID())
360		}
361		if info, _ := n.Tx(midID); info.ReplacedBy != lastID {
362			t.Fatalf("mid link rewired to %s, want still %s", info.ReplacedBy, lastID)
363		}
364		if info, _ := n.Tx(origID); info.ReplacedBy != midID {
365			t.Fatalf("orig link rewired to %s, want still %s", info.ReplacedBy, midID)
366		}
367		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{final.ID(): "waiting-pack"})
368	}
